float qy = LGBOAbs(y) - (halfHeight - radius);
float outsideX = LGBOMax(qx, 0.0f);
float outsideY = LGBOMax(qy, 0.0f);
float outside = LGBOHypot(outsideX, outsideY);
float inside = LGBOMin(LGBOMax(qx, qy), 0.0f);
